import{c as a,Q as t,j as r,m as o}from"./chunks/framework.BXc4yaFE.js";const d=JSON.parse('{"title":"HALO: Hierarchical Autonomous Logic-Oriented Orchestration for Multi-Agent LLM Systems","description":"","frontmatter":{"url":"https://arxiv.org/abs/2505.13516","title":"HALO: Hierarchical Autonomous Logic-Oriented Orchestration for Multi-Agent LLM Systems","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2505.13516,"authors":["Zhipeng Hou","Junyi Tang","Yipeng Wang"],"domains":["cs.MA"],"html":"https://arxiv.org/html/2505.13516v1","pdf_path":"pdfs/2505.13516.pdf","published_date":"2025-05-17T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2025-05-17-halo-hierarchical-orchestration-multi-agent-2505-13516.md","filePath":"research/papers/2025-05-17-halo-hierarchical-orchestration-multi-agent-2505-13516.md","lastUpdated":1785909234000}'),i={name:"research/papers/2025-05-17-halo-hierarchical-orchestration-multi-agent-2505-13516.md"};function n(s,e,l,c,h,g){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="halo-hierarchical-autonomous-logic-oriented-orchestration-for-multi-agent-llm-systems" tabindex="-1">HALO: Hierarchical Autonomous Logic-Oriented Orchestration for Multi-Agent LLM Systems <a class="header-anchor" href="#halo-hierarchical-autonomous-logic-oriented-orchestration-for-multi-agent-llm-systems" aria-label="Permalink to &quot;HALO: Hierarchical Autonomous Logic-Oriented Orchestration for Multi-Agent LLM Systems&quot;">​</a></h1><p><strong>Authors</strong>: Zhipeng Hou, Junyi Tang, Yipeng Wang <strong>Published</strong>: May 17, 2025 <strong>Source</strong>: <a href="https://arxiv.org/abs/2505.13516" target="_blank" rel="noreferrer">https://arxiv.org/abs/2505.13516</a> · <a href="https://arxiv.org/html/2505.13516v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2505.13516 <strong>Categories</strong>: cs.MA <strong>PDF</strong>: <a href="https://arxiv.org/abs/2505.13516" target="_blank" rel="noreferrer">research/papers/pdfs/2505.13516.pdf</a> (10 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Recent advancements in Multi-Agent Systems (MAS) powered by Large Language Models (LLMs) have demonstrated tremendous potential in diverse task scenarios. Nonetheless, existing agentic systems typically rely on predefined agent-role design spaces and static communication structures, limiting their adaptability as well as flexibility in complex interaction environments and leading to subpar performance on highly specialized and expert-level tasks. To address these issues, we introduce HALO, a multi-agent collaboration framework based on a hierarchical reasoning architecture. Specifically, we incorporate a high-level planning agent for task decomposition, mid-level role-design agents for subtask-specific agent instantiation, and low-level inference agents for subtask execution. Particularly, subtask execution is reformulated as a structured workflow search problem, where Monte Carlo Tree Search (MCTS) systematically explores the agentic action space to construct optimal reasoning trajectories. Additionally, as the majority of users lack expertise in prompt engineering, we leverage an Adaptive Prompt Refinement module to transform raw queries into task-specific prompts. Empirical evaluations on Code Generation (HumanEval), General Reasoning (MMLU), and Arithmetic Reasoning (MATH) benchmark datasets highlight the effectiveness of HALO, yielding a 14.4% average improvement over state-of-the-art baselines. Notably, HALO achieves up to 13.3% performance gain on the Moral Scenarios subject in the MMLU benchmark and up to 19.6% performance gain on the Algebra subarea in the MATH benchmark, indicating its advanced proficiency in tackling highly specialized and expert-level tasks.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>提出 <strong>HALO</strong>：基於 hierarchical reasoning 架構的 multi-agent 協作框架，針對既有 MAS 依賴「預定義 agent-role 設計空間 + static communication structure」造成的低適應性問題。</li><li>三層 agent 架構：<strong>high-level planning agent</strong>（task decomposition）→ <strong>mid-level role-design agents</strong>（針對 subtask 動態 instantiate agent）→ <strong>low-level inference agents</strong>（subtask execution）。</li><li>將 subtask execution 重構為 <strong>structured workflow search problem</strong>，以 <strong>Monte Carlo Tree Search (MCTS)</strong> 系統性探索 agentic action space，建構最優 reasoning trajectory。</li><li><strong>Adaptive Prompt Refinement</strong> 模組：將使用者原始 query 自動轉成 task-specific prompt，降低對 prompt engineering 專業的依賴。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>對 SOTA baselines 平均提升 <strong>14.4%</strong>（跨 HumanEval / MMLU / MATH 三 benchmark）。</li><li>MMLU 的 <strong>Moral Scenarios</strong> 子科目最高提升 <strong>13.3%</strong>。</li><li>MATH 的 <strong>Algebra</strong> 子領域最高提升 <strong>19.6%</strong>。</li><li>結論訴求：在高度專業化、expert-level 任務上展現優勢。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><p>文件未列明確 limitation 章節（依 abstract 判讀）。推測弱點：</p><ul><li>MCTS workflow search 的計算成本 / token 開銷未在 abstract 量化，動態三層 + 樹搜索可能 inference cost 偏高。</li><li>評測僅限 HumanEval / MMLU / MATH 三個 well-defined benchmark，缺 open-ended 或長程 agentic 任務驗證泛化性。</li><li>「動態 role instantiation」的穩定性與失敗模式（如 role 設計偏移）未在摘要層交代。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>直接對映 subagent fan-out</strong>：HALO 的 planning → role-design → inference 三層，對應本 workspace「主對話規劃分工 → spawn 專責 sub-agent → child 執行」拓撲（見 <code>core.md §PROPOSE 委派</code>（原 <code>subagent-strategy.md</code>） Hierarchical Fan-out）。其「動態 role-design」比本 workspace 的固定 agent type 清單更激進。⚠️ 落地門檻：本 workspace fan-out 上限 4 且 child 不自溝通，HALO 的 MCTS workflow search 需更大樹寬度，直接套用會撞 fan-out 與 token budget 上限。 〔v5.1：所引 workspace 細則已退役 → 見 <code>INDEX.md</code> §v5.1 規則退役對照〕</li><li><strong>MCTS workflow search vs The Loop</strong>：HALO 以 MCTS 探索 action space 找最優 trajectory，與 The Loop 的 PROPOSE→APPLY→TEST 迭代收斂屬不同範式（搜索 vs 機械驗證迭代）；可借鏡其「reformulate execution as search」但須保留 workspace 的 deterministic verification gate（搜索結果仍需 unverified_success 親驗）。</li><li><strong>Adaptive Prompt Refinement</strong> 概念上接近 workspace 的 IDENTIFY 階段（顯露假設、把模糊 query 結構化），但 HALO 自動化、workspace 偏人工 spec。⚠️ 自動 refine 與「off-rails 不靜默委派」紀律有張力，需人驗證閘。</li><li>評測 14.4% 平均增益為論文自報數字，採信前應對照 baseline 設定；屬 multi-agent orchestration 領域的可參考實證，非可直接移植的工程結論。</li></ul>',17)])])}const p=a(i,[["render",n]]);export{d as __pageData,p as default};
